// Package show holds the light shows built into the firmware: the original iCubeSmart cartoons
// as Go functions (generated by tools/showgen, see dynamic.go, audio.go, test.go and library.go).
package show

import "github.com/Tariomka/stm32-led-cube/internal/engine/keyframe"

// Group is the show mode selected with DIP switches SW1/SW2 at power-up.
type Group int

const (
	Dynamic Group = iota // SW1 = 1, SW2 = 1
	Audio                // SW1 = 0, SW2 = 1: cartoons follow the microphone
	Test                 // SW1 = 1, SW2 = 0: LED test patterns
	Text                 // SW1 = 0, SW2 = 0: shows uploaded from the PC or the Pico
)

var library = &keyframe.Library{Shapes: shapes, Palettes: palettes}

// Show returns the built-in show of a group, or nil for Text (uploaded shows).
func Show(group Group) *keyframe.Show {
	var cartoons []func() *keyframe.Cartoon
	switch group {
	case Dynamic:
		cartoons = dynamicCartoons
	case Audio:
		cartoons = audioCartoons
	case Test:
		cartoons = testCartoons
	default:
		return nil
	}
	return &keyframe.Show{Cartoons: cartoons, Keys: Keys}
}

// SetMissing reports unknown shape or palette names (diagnostics).
func SetMissing(report func(kind, name string)) {
	library.Missing = report
}
